UPDATE `quest_template_locale` SET `Details` = 'Le Orchesse... quelle non ti ashcoltano proprio... hic! Mi hai capito, $r?$B$BKurzel è con noi da anni, ormai dovrebbe aver capito come facciamo le coshe. Attiriamo gli shtupidi per fargli fare il lavoro pericolosho e poi, quando è il momento giusto, ci teniamo tutta la ricompensha. Non è coshì difficile da capire!$B$BNon lei, però... Quella pelleverde impaziente fa tutto da shola! Probabilmente ora è morta... ma mi shentirei troppo in colpa she non andasshimo a cercarla. Però non me la shento di farlo pershonalmente... hic!$B$BAllora, ci pensi tu?', `VerifiedBuild` = 0 WHERE `ID` = 12037 AND `locale` = 'itIT';
