-- Quest reward texts
DELETE FROM `quest_offer_reward_locale` WHERE `locale` = 'itIT' AND `ID` IN (86, 188, 476, 877, 2518, 3361, 6503, 7783, 9133, 11657, 11731, 11921, 11923, 11924, 11925, 11926, 12513, 13187, 13272);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(86, 'itIT', 'Anche se questa carne di cinghiale selvatico è dura, basta cuocerla a sufficienza per farne un delizioso pasticcio!', 0),
(188, 'itIT', 'Devo dire davvero notevole! Sei davvero un maestro della caccia alla tigre, $N!', 1),
(476, 'itIT', 'Per le stelle! È davvero terribile!', 1),
(877, 'itIT', 'Hai fatto delle scoperte incredibili! I semi che ti ho dato erano secchi e morti. Qualsiasi cosa ci sia sotto le oasi, è in grado di creare la vita dal nulla!$B$BDobbiamo fare altre ricerche...', 0),
(2518, 'itIT', 'La foresta piange Dama Sathrah, ma non potevamo agire altrimenti.$B$BGrazie, $N.', 1),
(3361, 'itIT', 'Urrà, le hai trovate! Sei un vero salvatore, amico mio. Ecco, non è molto, ma è qualcosa per il disturbo che ti ho causato! Grazie!', 0),
(6503, 'itIT', 'Molto bene, $N. Le tue abilità di cacciatore sono impressionanti...$B$BLa perdita di quelle staffette aiuta ad accecare l''Alleanza, e quando le mancano informazioni è meno propensa a lanciare attacchi.', 0),
(7783, 'itIT', 'Ancora una volta hai reso un grande onore all''Orda, $N. Il figlio di Alamorte è passato a miglior vita e di certo il maligno sta andando su tutte le furie.', 1),
(9133, 'itIT', 'Che cos''è questo? Il cervello marcio di Lymel è finalmente scivolato fuori dalla sua testa? Vuole tutta questa roba?!?$B$BHai portato qualcuno con te per aiutarti a trasportarla?', 0),
(11657, 'itIT', 'Afferrare al volo le torce è molto divertente, non trovi? Ma fai attenzione! Non vorrai ustionarti!', 0),
(11731, 'itIT', 'Presto! Non c''è tempo da perdere!', 0),
(11921, 'itIT', 'Ben fatto! Diventerai un vero giocoliere più velocemente della miccia di un petardo! Ora sbrigati: è con la prossima prova che la situazione si fa davvero... scottante.', 1),
(11923, 'itIT', 'Afferrare al volo le torce è molto divertente, non trovi? Ma fai attenzione! Non vorrai ustionarti!', 0),
(11924, 'itIT', 'Afferrare al volo le torce è molto divertente, non trovi? Ma fai attenzione! Non vorrai ustionarti!', 0),
(11925, 'itIT', 'Afferrare al volo le torce è molto divertente, non trovi? Ma fai attenzione! Non vorrai ustionarti!', 0),
(11926, 'itIT', 'Ben fatto! Diventerai un vero giocoliere più velocemente della miccia di un petardo! Ora sbrigati: è con la prossima prova che la situazione si fa davvero... scottante.', 1),
(12513, 'itIT', 'Il mio... il mio cappello! Ma... come hai fatto...?$B$BBe''... non importa. Dunque ora conosci il mio segreto. Sono stato battuto... una volta. Ecco, prendi questo cappello in cambio del mio. Te lo sei guadagnato.', 0),
(13187, 'itIT', 'Hai fatto un ottimo lavoro, $c.$B$BChe le tue gesta rinnovino la speranza del nostro popolo, affinché un giorno possiamo riconquistare la città dei nostri antenati.', 0),
(13272, 'itIT', 'Che tu possa uccidere molti umanoidi e prenderne la stoffa.', 0);

