INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(24, 'itIT', 'Saluti ancora, $N! Sei $gvenuto:venuta; a mostrarmi la prova della tua caccia?', 0),
(412, 'itIT', 'Il Tecno-Ricostituente sarà in funzione appena avremo abbastanza Ingranaggi Stabilizzatori e Ingranaggi Giromeccanici.', 0),
(848, 'itIT', 'Mi hai portato le spore, $N? Devo spedire una miscela a un mio socio a Picco del Tuono, e per prepararla servono le spore...', 0),
(7783, 'itIT', 'Vorrei tanto essere stato presente a vedere l''espressione della bestia nel momento in cui le hai inferto il colpo di grazia, $N.', 0),
(8311, 'itIT', 'Hai già finito di fare dolcetto o scherzetto? Sono triste di non poter venire perché sono malato, ma il tuo aiuto mi fa sentire un po'' meglio...', 0),
(8312, 'itIT', 'Hai già finito di fare dolcetto o scherzetto? Sono triste di non poter venire perché sono malata, ma il tuo aiuto mi fa sentire un po'' meglio...', 0),
(24451, 'itIT', 'Hai recuperato quel libro?', 0);

